import { Component } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { QrcropService } from '../service/qrcrop.service';

@Component({
  selector: 'app-crop-qr',
  imports: [],
  templateUrl: './crop-qr.component.html',
  styleUrl: './crop-qr.component.css'
})
export class CropQRComponent {
  croppedUrl: SafeUrl | null = null;
  error: string | null = null;
  image = "data:image/jpeg;base64,"
  constructor(private qrcrop:QrcropService,   private sanitizer: DomSanitizer){}

  ngOnInit(){
    this.cropBase64Image(this.image)
  }
  async cropBase64Image(base64: string) {
  try {
    // Base64 can be used directly as image src
    const croppedBlob = await this.qrcrop.cropOnlyQR(base64);
const blobUrl = URL.createObjectURL(croppedBlob);

    // Sanitize the blob URL
    this.croppedUrl = this.sanitizer.bypassSecurityTrustUrl(blobUrl);
  
    
    this.error = null;
  } catch (e: any) {
    this.error = e.message || 'Failed to crop QR';
    this.croppedUrl = null;
  }
}
}
